local set = {}
for _, id in ipairs(M.CATALOG) do set[id] = true end
local cache = {}

-- get(id): a Skill wrapper for ANY real catalog id, built on first use + cached; nil if
-- id is not a known skill row. define() sets .id and registers into object_manager.
function M.get(id)
    if not id or not set[id] then return nil end
    if cache[id] then return cache[id] end
    local h = Skill.define{ id = id }
    cache[id] = h
    return h
end

-- ---- CURATED wrapper (with hooks) ----

-- Fireball — a fire active skill. NOTE: the id "FlameThrower" is a DT_PartnerSkill
-- DevName-column value (the closest real fire active skill), NOT a row FName — the row
-- FNames in these two tables are encounter-keyed (RAID_/GYM_/BOSS_) or passive-trait
-- rows, so "FlameThrower" is NOT a CATALOG member (pre-seeded below). element/cooldown/
-- power are framework-side metadata (the dump lists schema columns, not per-row values).
M.Fireball = Skill.define{
    id       = "FlameThrower",
    kind     = "active",
    element  = "fire",
    cooldown = 3.0,
    power    = 50,
    events = {
        onActivate = function(self, owner, ctx)
            -- TODO: spawn the projectile through the native gameplay layer.
        end,
    },
}

-- Pre-seed curated so get("FlameThrower") returns the curated handle (hooks intact).
set[M.Fireball.id] = true
cache[M.Fireball.id] = M.Fireball

return M
